const DASHBOARD_ACTIONS=new Set(['toggle','token','chat','test','importUsage','runCodex','cancelCodex','range','retry','advisorRecommend','advisorApply','advisorFeedback']);
function validDashboardMessage(message){if(!message||typeof message!=='object'||Array.isArray(message)||!DASHBOARD_ACTIONS.has(message.action))return false;if(['range','retry'].includes(message.action)&&(typeof message.id!=='string'&&typeof message.id!=='number'))return false;if(typeof message.id==='string'&&message.id.length>160)return false;if(message.action==='advisorRecommend'&&(typeof message.task!=='string'||message.task.length>10000||!['speed','quality','cost'].includes(message.priority)))return false;if(message.action==='advisorApply'&&(typeof message.model!=='string'||message.model.length>160))return false;if(message.action==='advisorFeedback'&&(typeof message.model!=='string'||message.model.length>160||typeof message.category!=='string'||message.category.length>80||!['successful','partial','failed','not_rated'].includes(message.outcome)))return false;return true;}

function escapeHtml(value) { return String(value).replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c])); }
function shouldNotify(event, config) { if (event.test) return false; if (event.kind === 'completed') return config.get('enableNotifications', true); if (event.kind === 'attention') return config.get('notifyOnAttention', true); if (event.kind === 'failed') return config.get('notifyOnErrors', true); if(event.kind==='interrupted')return config.get('notifyOnCancellation',true); return false; }
const windowsResultMessage = result => ({ sent:'Windows accepted the notification. If no banner appeared, check Do Not Disturb and the notification center.', balloon_fallback:'Windows accepted the notification through the desktop balloon fallback.', notifications_disabled_global:'Windows notifications are disabled globally.', notifications_disabled_app:'Notifications are disabled for Visual Studio Code in Windows Settings.', identity_missing:'The registered Visual Studio Code notification identity was not found.', identity_denied:'Windows rejected the Visual Studio Code notification identity.', timeout:'PowerShell timed out while sending the notification.', process_start:'PowerShell could not be started.', unsupported_platform:'Native Windows notifications are only available on Windows.' }[result.category] || 'PowerShell could not send the Windows notification.');
async function nativeToast(context, message, output) { const result=await showWindowsToast({scriptPath:context.asAbsolutePath('scripts/windows-toast.ps1'),message}); output?.appendLine(`${new Date().toISOString()} Windows notification ${JSON.stringify({category:result.category,exitCode:result.exitCode??null,hresult:result.hresult??null})}`); return result; }

function usageMarkup(analytics) {
  const fmt=value=>Number(value||0).toLocaleString(), money=value=>`$${Number(value||0).toFixed(4)}`;
  if (!analytics.totals.records) return '<section class="integration"><b>Token usage &amp; cost analytics</b><div class="actions"><button data-action="range" data-id="7">7 days</button><button data-action="range" data-id="30">30 days</button><button data-action="range" data-id="0">All</button><button data-action="importUsage">Import JSON</button></div><div class="empty">No verified token usage data is available. AgentPilot never estimates usage from lifecycle events.</div></section>';
  const cards=[['Total tokens',fmt(analytics.totals.totalTokens)],['Input',fmt(analytics.totals.inputTokens)],['Output',fmt(analytics.totals.outputTokens)],['Cached input',fmt(analytics.totals.cachedInputTokens)],['Reasoning',fmt(analytics.totals.reasoningTokens)],['Estimated API cost',analytics.totals.pricedRecords?money(analytics.totals.estimatedCost):'Price unavailable']].map(([label,value])=>`<div class="card"><b>${value}</b><span>${label}</span></div>`).join('');
  const groups=map=>Object.entries(map).sort((a,b)=>b[1].totalTokens-a[1].totalTokens).map(([key,value])=>`<tr><td>${escapeHtml(key)}</td><td>${fmt(value.totalTokens)}</td><td>${value.pricedRecords?money(value.estimatedCost):'Unavailable'}</td></tr>`).join('');
  const daily=Object.entries(analytics.daily).sort().map(([day,value])=>`<tr><td>${day}</td><td>${fmt(value.totalTokens)}</td><td>${value.pricedRecords?money(value.estimatedCost):'Unavailable'}</td></tr>`).join('');
  const weekly=Object.entries(analytics.weekly).sort().map(([week,value])=>`<tr><td>Week of ${week}</td><td>${fmt(value.totalTokens)}</td><td>${value.pricedRecords?money(value.estimatedCost):'Unavailable'}</td></tr>`).join('');
  return `<section class="integration"><div class="integration-head"><div><b>Token usage &amp; cost analytics</b><div class="muted">Verified structured metadata only · ${analytics.totals.records} records</div></div><div class="actions"><button data-action="range" data-id="7">7 days</button><button data-action="range" data-id="30">30 days</button><button data-action="range" data-id="0">All</button><button data-action="importUsage">Import JSON</button></div></div><section class="cards">${cards}</section><h3>Codex versus Claude</h3><table><tbody>${groups(analytics.byProvider)}</tbody></table><h3>By model</h3><table><tbody>${groups(analytics.byModel)}</tbody></table><h3>By project</h3><table><tbody>${groups(analytics.byProject)}</tbody></table><h3>Daily usage</h3><table><thead><tr><th>Date</th><th>Tokens</th><th>Estimated cost</th></tr></thead><tbody>${daily}</tbody></table><h3>Weekly usage</h3><table><tbody>${weekly}</tbody></table><h3>Data sources and confidence</h3><table><tbody>${groups(analytics.bySource)}</tbody></table><div class="muted">Cost is an API-price estimate. Models without sourced pricing are reported as unavailable and excluded from totals.</div></section>`;
}

function taskMarkup(tasks = []) {
  const rows=tasks.map(task=>`<tr><td>${escapeHtml(task.startedAt)}</td><td>${escapeHtml(task.project)}</td><td><span class="pill">${escapeHtml(task.status)}</span></td><td>${task.durationMs==null?'—':`${Math.round(task.durationMs/1000)}s`}</td><td>${escapeHtml(task.errorCategory||'—')}</td></tr>`).join('');
  const running=tasks.some(task=>task.status==='running'||task.status==='cancelling');
  return `<section class="integration"><div class="integration-head"><div><b>AgentPilot-owned Codex tasks</b><div class="muted">Only tasks launched by AgentPilot are monitored</div></div><div class="actions"><button data-action="runCodex">Run Codex Task</button>${running?'<button data-action="cancelCodex">Cancel running task</button>':''}</div></div><table><thead><tr><th>Started</th><th>Project</th><th>Status</th><th>Duration</th><th>Result</th></tr></thead><tbody>${rows||'<tr><td colspan="5">No AgentPilot-owned tasks yet.</td></tr>'}</tbody></table></section>`;
}

function advisorMarkup(state={models:[],result:null}){
  const models=Array.isArray(state.models)?state.models:[],result=state.result;
  const catalog=models.map(model=>`<li><b>${escapeHtml(model.displayName||model.id)}</b> <span class="muted">${escapeHtml(model.description||'Capabilities, cost, and speed unknown.')}</span></li>`).join('');
  let resultHtml='<div class="empty">Describe a task to get a local, deterministic recommendation. The task text is not stored.</div>';
  if(result){const recommended=result.candidates.find(item=>item.id===result.recommendedModelId),rows=result.candidates.map(item=>`<tr><td><b>${escapeHtml(item.displayName)}</b>${item.isDefault?' <span class="pill">catalog default</span>':''}</td><td>${item.score}</td><td>${item.reasons.map(reason=>escapeHtml(reason)).join('<br>')}</td><td><button data-action="advisorApply" data-model="${escapeHtml(item.id)}">New chat</button></td></tr>`).join('');resultHtml=`<div class="advisor-result"><p><b>${result.neutral?'Neutral result':'Recommendation'}:</b> ${escapeHtml(result.summary)}</p><p>Task category: <span class="pill">${escapeHtml(result.classification.label)}</span> · Complexity: <span class="pill">${escapeHtml(result.complexity.level)}</span> · Priority: <span class="pill">${escapeHtml(result.priority)}</span></p><table><thead><tr><th>Available model</th><th>Evidence score</th><th>Reasons</th><th>Action</th></tr></thead><tbody>${rows}</tbody></table><div class="muted">${result.limitations.map(value=>escapeHtml(value)).join(' ')}</div>${recommended?`<div class="actions"><span class="muted">Optional subjective feedback for ${escapeHtml(recommended.displayName)}:</span><button data-action="advisorFeedback" data-model="${escapeHtml(recommended.id)}" data-category="${escapeHtml(result.classification.category)}" data-outcome="successful">Successful</button><button data-action="advisorFeedback" data-model="${escapeHtml(recommended.id)}" data-category="${escapeHtml(result.classification.category)}" data-outcome="partial">Partially successful</button><button data-action="advisorFeedback" data-model="${escapeHtml(recommended.id)}" data-category="${escapeHtml(result.classification.category)}" data-outcome="failed">Failed</button></div>`:''}</div>`;}
  return `<section class="integration"><div class="integration-head"><div><b>Smart Model Advisor</b><div class="muted">Local deterministic analysis · verified Codex model catalog only</div></div><span class="pill">${models.length} available</span></div><label for="advisor-task">Task description (not stored)</label><textarea id="advisor-task" maxlength="10000" placeholder="Example: Debug a concurrency regression across several files"></textarea><div class="actions"><select id="advisor-priority" aria-label="Advisor priority"><option value="quality">Quality</option><option value="speed">Speed</option><option value="cost">Estimated API-equivalent cost</option></select><button data-action="advisorRecommend">Recommend</button></div>${resultHtml}<details><summary>Available models from model/list</summary><ul>${catalog||'<li>No model catalog is available.</li>'}</ul></details><div class="muted">The Advisor never executes the task and never changes an active conversation.</div></section>`;
}

function recommendFromDashboardMessage(message,{models=[],usageRecords=[],feedback=[]}={}){return recommend({task:message.task,priority:message.priority,models,usageRecords,feedback});}

function legacyRender(events, telegram, analytics = usageAnalytics([], new CostEstimator()), nonce = '', tasks = [], advisor={models:[],result:null}) {
  if (typeof analytics === 'string') { nonce = analytics; analytics = usageAnalytics([], new CostEstimator()); }
  const data=dashboardData(events),cards=[['All events',data.total],['Codex',data.codex],['Claude',data.claude],['Test events',data.tests]].map(([label,value])=>`<div class="card"><b>${value}</b><span>${label}</span></div>`).join('');
  const rows=data.recent.map(event=>`<tr class="${event.test?'test':''}"><td>${escapeHtml(new Date(event.time).toLocaleString())}</td><td><span class="pill">${escapeHtml(event.agent)}</span></td><td>${escapeHtml(event.kind)}</td><td>${escapeHtml(event.project)}</td><td>${event.test?'Test':'Real'}</td></tr>`).join(''),telegramStatus=telegram.connected?'Connected':'Disconnected';
  const deliveryCards=['sent','pending','failed','uncertain'].map(status=>`<div class="card"><b>${telegram.history.counts[status]||0}</b><span>${status}</span></div>`).join(''),deliveries=telegram.history.recent.map(item=>`<tr><td>${escapeHtml(item.updatedAt||item.createdAt)}</td><td>${escapeHtml(item.agent)} / ${escapeHtml(item.kind)}</td><td><span class="pill">${escapeHtml(item.status)}</span></td><td>${Number(item.attemptCount)||0}</td><td>${escapeHtml(item.lastErrorCategory||'—')}</td><td>${['failed','uncertain'].includes(item.status)?`<button data-action="retry" data-id="${escapeHtml(item.sourceEventId)}">Retry</button>`:'—'}</td></tr>`).join('');
  const css=`:root{color-scheme:dark}body{font-family:var(--vscode-font-family);padding:24px;color:var(--vscode-foreground);background:var(--vscode-editor-background)}header,.integration-head{display:flex;justify-content:space-between;align-items:center;gap:12px}h1{margin:0;font-size:24px}.muted{color:var(--vscode-descriptionForeground)}.cards{display:grid;grid-template-columns:repeat(4,minmax(110px,1fr));gap:12px;margin:24px 0}.card,.integration{padding:16px;border:1px solid var(--vscode-panel-border);border-radius:8px;background:var(--vscode-sideBar-background)}.card b{font-size:26px;display:block}.card span{color:var(--vscode-descriptionForeground);text-transform:capitalize}.integration{margin-bottom:24px}.actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-top:12px}.empty{padding:28px;margin-top:16px;text-align:center;border:1px dashed var(--vscode-panel-border);color:var(--vscode-descriptionForeground)}button{color:var(--vscode-button-foreground);background:var(--vscode-button-background);border:0;padding:7px 12px;border-radius:3px;cursor:pointer}button:hover{background:var(--vscode-button-hoverBackground)}textarea{box-sizing:border-box;width:100%;min-height:72px;margin-top:8px;padding:8px;color:var(--vscode-input-foreground);background:var(--vscode-input-background);border:1px solid var(--vscode-input-border);font:inherit}select{padding:7px;color:var(--vscode-dropdown-foreground);background:var(--vscode-dropdown-background);border:1px solid var(--vscode-dropdown-border)}details{margin-top:14px}.status{margin-bottom:16px}.pill{padding:2px 7px;border-radius:9px;background:var(--vscode-badge-background);color:var(--vscode-badge-foreground)}table{width:100%;border-collapse:collapse;margin-bottom:24px}th,td{padding:10px;text-align:left;vertical-align:top;border-bottom:1px solid var(--vscode-panel-border)}th{color:var(--vscode-descriptionForeground)}tr.test{opacity:.6}@media(max-width:650px){.cards{grid-template-columns:repeat(2,1fr)}}`;
  const telegramMarkup=`<section class="integration"><div class="integration-head"><div><b>Telegram</b><div class="muted">${telegramStatus} · ${telegram.enabled?'Enabled':'Disabled'}</div></div><span class="pill">${telegramStatus}</span></div><div class="actions"><button data-action="toggle">${telegram.enabled?'Disable':'Enable'} Telegram</button><button data-action="token">Configure token</button><button data-action="chat">Configure chat ID</button><button data-action="test">Send test</button></div><section class="cards">${deliveryCards}</section><table><thead><tr><th>Updated</th><th>Notification</th><th>Status</th><th>Attempts</th><th>Failure</th><th>Action</th></tr></thead><tbody>${deliveries||'<tr><td colspan="6">No delivery history yet.</td></tr>'}</tbody></table><div class="muted">Uncertain means Telegram may already have accepted the message. Retry only after checking the destination.</div></section>`;
  const script=`const vscode=acquireVsCodeApi();document.querySelectorAll('button[data-action]').forEach(button=>button.addEventListener('click',()=>{const action=button.dataset.action;if(action==='advisorRecommend')vscode.postMessage({action,task:document.getElementById('advisor-task').value,priority:document.getElementById('advisor-priority').value});else if(action==='advisorApply')vscode.postMessage({action,model:button.dataset.model});else if(action==='advisorFeedback')vscode.postMessage({action,model:button.dataset.model,category:button.dataset.category,outcome:button.dataset.outcome});else vscode.postMessage({action,id:button.dataset.id});}));`;
  return `<!doctype html><html><head><meta charset="UTF-8"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'nonce-${nonce}'"><style>${css}</style></head><body><header><div><h1>AgentPilot</h1><div class="muted">Local agent activity</div></div><div class="muted">Real events: ${data.real}</div></header><section class="cards">${cards}</section>${advisorMarkup(advisor)}${taskMarkup(tasks)}${usageMarkup(analytics)}${telegramMarkup}<div class="status">Codex: <b>${data.status.codex}</b> &nbsp; Claude: <b>${data.status.claude}</b> <span class="muted">(derived only from observed events)</span></div><table><thead><tr><th>Time</th><th>Agent</th><th>Event</th><th>Project</th><th>Source</th></tr></thead><tbody>${rows||'<tr><td colspan="5">No events captured yet.</td></tr>'}</tbody></table><script nonce="${nonce}">${script}</script></body></html>`;
}

function miniUsageChart(analytics){const entries=Object.entries(analytics.daily||{}).sort().slice(-14),max=Math.max(1,...entries.map(([,value])=>Number(value.totalTokens)||0));if(!entries.length)return'<div class="empty compact">No verified usage points in this range.</div>';return `<div class="mini-chart" role="img" aria-label="Verified daily token usage for the latest ${entries.length} days">${entries.map(([day,value])=>{const tokens=Number(value.totalTokens)||0,height=Math.max(3,Math.round(tokens/max*100));return `<div class="bar-cell" title="${escapeHtml(day)}: ${tokens.toLocaleString()} tokens"><span class="bar" style="height:${height}%"></span><small>${escapeHtml(day.slice(5))}</small></div>`;}).join('')}</div>`;}

function render(events,telegram,analytics=usageAnalytics([],new CostEstimator()),nonce='',tasks=[],advisor={models:[],result:null}){
  if(typeof analytics==='string'){nonce=analytics;analytics=usageAnalytics([],new CostEstimator());}
  telegram=telegram||{connected:false,enabled:false,history:{counts:{},recent:[]}};telegram.history=telegram.history||{counts:{},recent:[]};
  const data=dashboardData(events),fmt=value=>Number(value||0).toLocaleString(),models=Object.keys(analytics.byModel||{}).length,deliveryFailures=(telegram.history.counts.failed||0)+(telegram.history.counts.uncertain||0);
  const cards=[['Sessions',data.real,'Observed lifecycle events'],['Verified tokens',fmt(analytics.totals.totalTokens),'Structured usage only'],['Models',models,'Observed in usage records'],['Notification health',deliveryFailures?'Needs attention':'Healthy',deliveryFailures?`${deliveryFailures} failed or uncertain`:'No delivery failures']].map(([label,value,note])=>`<article class="metric"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong><small>${escapeHtml(note)}</small></article>`).join('');
  const activity=data.recent.map(event=>`<li class="timeline-item ${event.test?'test':''}"><span class="timeline-mark status-dot ${escapeHtml(event.kind)}"></span><div><b>${escapeHtml(event.agent)} · ${escapeHtml(event.kind)}</b><p>${escapeHtml(event.project)} · ${event.test?'Test event':'Real event'}</p></div><time>${escapeHtml(new Date(event.time).toLocaleString())}</time></li>`);
  const eventRows=data.recent.map(event=>`<tr class="${event.test?'test':''}"><td>${escapeHtml(new Date(event.time).toLocaleString())}</td><td><span class="pill">${escapeHtml(event.agent)}</span></td><td>${escapeHtml(event.kind)}</td><td>${escapeHtml(event.project)}</td><td>${event.test?'Test':'Real'}</td></tr>`).join('');
  const telegramStatus=telegram.connected?'Connected':'Disconnected',deliveryCards=['sent','pending','failed','uncertain'].map(status=>`<article class="metric small"><span>${status}</span><strong>${telegram.history.counts[status]||0}</strong></article>`).join(''),deliveries=(telegram.history.recent||[]).map(item=>`<tr><td>${escapeHtml(item.updatedAt||item.createdAt)}</td><td>${escapeHtml(item.agent)} / ${escapeHtml(item.kind)}</td><td><span class="pill"><i class="status-dot ${escapeHtml(item.status)}"></i>${escapeHtml(item.status)}</span></td><td>${Number(item.attemptCount)||0}</td><td>${escapeHtml(item.lastErrorCategory||'—')}</td><td>${['failed','uncertain'].includes(item.status)?`<button class="button ghost" data-action="retry" data-id="${escapeHtml(item.sourceEventId)}">Retry</button>`:'—'}</td></tr>`).join('');
  const telegramMarkup=`<section class="panel"><div class="panel-head"><div><p class="eyebrow">Telegram Bot API</p><h2>Delivery</h2><p class="muted">Credentials remain in VS Code SecretStorage.</p></div><span class="pill"><i class="status-dot ${telegram.connected?'sent':'failed'}"></i>${telegramStatus} · ${telegram.enabled?'Enabled':'Disabled'}</span></div><div class="toolbar"><button class="button" data-action="toggle">${telegram.enabled?'Disable':'Enable'} Telegram</button><button class="button secondary" data-action="token">Configure token</button><button class="button secondary" data-action="chat">Configure chat ID</button><button class="button secondary" data-action="test">Send test</button></div><div class="metrics compact-grid">${deliveryCards}</div><div class="table-wrap"><table><thead><tr><th>Updated</th><th>Notification</th><th>Status</th><th>Attempts</th><th>Failure</th><th></th></tr></thead><tbody>${deliveries||'<tr><td colspan="6"><div class="empty compact">No delivery history yet.</div></td></tr>'}</tbody></table></div><p class="callout">Uncertain means Telegram may already have accepted the message. Check the destination before retrying.</p></section>`;
  const tabs=[['overview','dashboard','Overview'],['advisor','sparkles','Advisor'],['usage','chart','Usage'],['activity','activity','Activity'],['notifications','bell','Notifications'],['settings','settings','Settings']].map(([id,glyph,label])=>`<button class="nav-item" role="tab" aria-selected="false" aria-controls="view-${id}" data-tab="${id}">${icon(glyph,label)}</button>`).join('');
  const css=`${baseCss}.app{min-height:100vh}.app-header{height:58px;padding:0 22px;border-bottom:1px solid var(--ap-border);display:flex;align-items:center;justify-content:space-between;position:sticky;top:0;background:var(--vscode-editor-background);z-index:4}.brand{display:flex;align-items:center;gap:10px}.brand-mark{display:grid;place-items:center;width:28px;height:28px;border:1px solid var(--ap-border);border-radius:7px;background:var(--ap-surface-raised)}.brand h1{font-size:15px;margin:0}.brand p{font-size:11px;margin:1px 0 0}.shell{display:grid;grid-template-columns:178px minmax(0,1fr);min-height:calc(100vh - 58px)}.nav{padding:16px 10px;border-right:1px solid var(--ap-border);background:var(--ap-surface);position:sticky;top:58px;height:calc(100vh - 58px)}.nav-item{display:flex;width:100%;align-items:center;gap:9px;border:0;border-radius:6px;padding:8px 10px;margin:2px 0;color:var(--ap-muted);background:transparent;text-align:left}.nav-item:hover{color:var(--vscode-foreground);background:var(--vscode-list-hoverBackground)}.nav-item[aria-selected=true]{color:var(--vscode-list-activeSelectionForeground);background:var(--vscode-list-activeSelectionBackground)}.content{padding:28px clamp(16px,4vw,48px);max-width:1240px;width:100%;margin:0 auto}.view[hidden]{display:none}.page-head{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;margin-bottom:22px}.page-head h2{font-size:22px;margin:0 0 5px}.page-head p{margin:0}.eyebrow{text-transform:uppercase;letter-spacing:.09em;font-size:10px;color:var(--ap-muted);margin:0 0 5px}.metrics{display:grid;grid-template-columns:repeat(4,minmax(130px,1fr));gap:10px;margin:18px 0}.metric{padding:14px;border:1px solid var(--ap-border);border-radius:var(--ap-radius);background:var(--ap-surface-raised);min-width:0}.metric span,.metric small{display:block;color:var(--ap-muted)}.metric strong{display:block;font-size:21px;line-height:1.25;margin:5px 0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.metric.small strong{font-size:18px}.panel,.integration{padding:18px;border:1px solid var(--ap-border);border-radius:var(--ap-radius-lg);background:var(--ap-surface-raised);margin:0 0 14px}.panel-head,.integration-head{display:flex;align-items:flex-start;justify-content:space-between;gap:14px}.panel h2,.integration b{margin:0}.grid-2{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(280px,.85fr);gap:14px}.toolbar,.actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:12px}.button,button:not(.nav-item){border:1px solid transparent;padding:7px 11px;border-radius:5px;color:var(--vscode-button-foreground);background:var(--vscode-button-background)}.button:hover,button:not(.nav-item):hover{background:var(--vscode-button-hoverBackground)}.button.secondary,.button.ghost{color:var(--vscode-foreground);background:var(--vscode-secondaryButton-background);border-color:var(--ap-border)}textarea,select,input{color:var(--vscode-input-foreground);background:var(--vscode-input-background);border:1px solid var(--vscode-input-border);border-radius:5px;padding:8px}textarea{width:100%;min-height:92px;resize:vertical;margin-top:8px}.empty{padding:36px 16px;text-align:center;border:1px dashed var(--ap-border);border-radius:7px;color:var(--ap-muted);margin-top:14px}.empty.compact{padding:18px;margin:0}.timeline{list-style:none;padding:0;margin:4px 0}.timeline-item{display:grid;grid-template-columns:10px minmax(0,1fr) auto;gap:11px;padding:11px 2px;border-bottom:1px solid var(--ap-border);align-items:start}.timeline-item p{margin:3px 0 0;color:var(--ap-muted)}.timeline-item time{font-size:11px;color:var(--ap-muted)}.timeline-item.test{opacity:.65}.timeline-mark{margin-top:5px}.mini-chart{height:180px;display:flex;gap:5px;align-items:flex-end;padding-top:12px}.bar-cell{height:100%;flex:1;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;min-width:8px}.bar{width:min(22px,75%);background:var(--vscode-charts-blue,var(--ap-accent));border-radius:3px 3px 1px 1px;min-height:3px}.bar-cell small{font-size:9px;color:var(--ap-muted);margin-top:5px;writing-mode:vertical-rl;display:none}.table-wrap{overflow:auto;margin-top:14px}table{width:100%;border-collapse:collapse}th,td{padding:9px 10px;text-align:left;vertical-align:top;border-bottom:1px solid var(--ap-border)}th{font-size:11px;color:var(--ap-muted);font-weight:600}tr.test{opacity:.65}.compact-grid{margin:14px 0}.callout{padding:10px;border-left:2px solid var(--ap-warn);background:var(--vscode-textBlockQuote-background);color:var(--ap-muted)}details{margin-top:14px}summary{cursor:pointer}.advisor-result{margin-top:16px}.status-strip{display:flex;gap:8px;flex-wrap:wrap}.privacy-list{display:grid;gap:8px;padding:0;list-style:none}.privacy-list li{display:flex;gap:8px;align-items:center}.privacy-list .icon{color:var(--ap-good)}@media(max-width:820px){.shell{grid-template-columns:1fr}.nav{position:sticky;top:58px;height:auto;display:flex;overflow:auto;border-right:0;border-bottom:1px solid var(--ap-border);padding:7px;z-index:3}.nav-item{width:auto;flex:0 0 auto;margin:0 2px}.content{padding-top:20px}.grid-2{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,minmax(120px,1fr))}}@media(max-width:470px){.app-header{padding:0 12px}.header-meta{display:none}.nav-item span{display:none}.nav-item{padding:8px 11px}.content{padding:16px 10px}.metrics{grid-template-columns:1fr 1fr}.metric{padding:11px}.page-head{display:block}.status-strip{margin-top:10px}.panel,.integration{padding:13px}.timeline-item{grid-template-columns:10px 1fr}.timeline-item time{grid-column:2}.table-wrap{margin-inline:-13px}th,td{padding:8px}}`;
  const script=`const vscode=acquireVsCodeApi(),saved=vscode.getState()||{},tabs=[...document.querySelectorAll('[data-tab]')],views=[...document.querySelectorAll('.view')];function selectTab(id,focus=false){if(!tabs.some(tab=>tab.dataset.tab===id))id='overview';for(const tab of tabs){const active=tab.dataset.tab===id;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;if(active&&focus)tab.focus();}for(const view of views)view.hidden=view.id!=='view-'+id;vscode.setState({...vscode.getState(),dashboardTab:id});}tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectTab(tab.dataset.tab));tab.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();let next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;selectTab(tabs[next].dataset.tab,true);});});selectTab(saved.dashboardTab||'overview');document.querySelectorAll('button[data-action]').forEach(button=>button.addEventListener('click',()=>{const action=button.dataset.action;if(action==='advisorRecommend')vscode.postMessage({action,task:document.getElementById('advisor-task').value,priority:document.getElementById('advisor-priority').value});else if(action==='advisorApply')vscode.postMessage({action,model:button.dataset.model});else if(action==='advisorFeedback')vscode.postMessage({action,model:button.dataset.model,category:button.dataset.category,outcome:button.dataset.outcome});else vscode.postMessage({action,id:button.dataset.id});}));document.getElementById('advisor-task')?.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key==='Enter'){event.preventDefault();document.querySelector('[data-action=advisorRecommend]')?.click();}});`;
  return `<!doctype html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'nonce-${nonce}'"><style>${css}</style></head><body><div class="app"><header class="app-header"><div class="brand"><span class="brand-mark">${icon('bot')}</span><div><h1>AgentPilot</h1><p class="muted">Local developer command center</p></div></div><div class="header-meta muted">v0.9 beta · ${data.real} real events</div></header><div class="shell"><nav class="nav" role="tablist" aria-label="Dashboard sections">${tabs}</nav><main class="content"><section class="view" id="view-overview" role="tabpanel"><div class="page-head"><div><p class="eyebrow">Workspace intelligence</p><h2>Overview</h2><p class="muted">Verified activity from AgentPilot-owned and supported agent workflows.</p></div><div class="status-strip"><span class="pill"><i class="status-dot ${data.status.codex==='error'?'failed':'ready'}"></i>Codex ${escapeHtml(data.status.codex)}</span><span class="pill"><i class="status-dot"></i>Claude ${escapeHtml(data.status.claude)}</span></div></div><div class="metrics">${cards}</div><div class="grid-2"><section class="panel"><div class="panel-head"><div><p class="eyebrow">Verified usage</p><h2>Token activity</h2></div><span class="pill">${analytics.totals.records||0} records</span></div>${miniUsageChart(analytics)}<p class="muted">Counts are read from structured usage events; costs, when shown, are estimates.</p></section><section class="panel"><div class="panel-head"><div><p class="eyebrow">Recent</p><h2>Activity timeline</h2></div></div><ol class="timeline">${activity.slice(0,6).join('')||'<li class="empty compact">No activity yet.</li>'}</ol></section></div>${taskMarkup(tasks)}</section><section class="view" id="view-advisor" role="tabpanel" hidden><div class="page-head"><div><p class="eyebrow">Explainable selection</p><h2>Smart Model Advisor</h2><p class="muted">Local deterministic guidance from available model evidence.</p></div></div>${advisorMarkup(advisor)}</section><section class="view" id="view-usage" role="tabpanel" hidden><div class="page-head"><div><p class="eyebrow">Structured metadata</p><h2>Usage</h2><p class="muted">Verified token counts and clearly labeled cost estimates.</p></div></div>${usageMarkup(analytics)}</section><section class="view" id="view-activity" role="tabpanel" hidden><div class="page-head"><div><p class="eyebrow">Lifecycle log</p><h2>Activity</h2><p class="muted">Real and simulated events are always distinguished.</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Time</th><th>Agent</th><th>Event</th><th>Project</th><th>Source</th></tr></thead><tbody>${eventRows||'<tr><td colspan="5"><div class="empty compact">No events captured yet.</div></td></tr>'}</tbody></table></div></section></section><section class="view" id="view-notifications" role="tabpanel" hidden><div class="page-head"><div><p class="eyebrow">Delivery health</p><h2>Notifications</h2><p class="muted">Telegram, Windows, and VS Code delivery remain independent.</p></div></div>${telegramMarkup}</section><section class="view" id="view-settings" role="tabpanel" hidden><div class="page-head"><div><p class="eyebrow">Local-first controls</p><h2>Settings &amp; privacy</h2><p class="muted">Sensitive configuration stays in VS Code and your local profile.</p></div></div><div class="grid-2"><section class="panel"><h2>Privacy boundary</h2><ul class="privacy-list"><li>${icon('check')}No prompts or source code in analytics</li><li>${icon('check')}Telegram credentials use SecretStorage</li><li>${icon('check')}No remote dashboard dependencies</li><li>${icon('check')}Explicit process and action approvals</li></ul></section><section class="panel"><h2>Utilities</h2><div class="toolbar"><button class="button secondary" data-action="importUsage">Import usage JSON</button><button class="button secondary" data-action="runCodex">Run Codex task</button></div><p class="muted">Additional preferences are available in VS Code Settings under AgentPilot.</p></section></div></section></main></div></div><div class="sr-only" aria-live="polite" id="announcer"></div><script nonce="${nonce}">${script}</script></body></html>`;
}

function activate(context) {
  const base = path.join(os.homedir(), '.agentpilot'), file = path.join(base, 'events.jsonl'), queueFile = path.join(base, 'telegram-deliveries.json'), usageFile = path.join(base, 'usage.json'), taskFile=path.join(base,'codex-tasks.json'), chatFile=path.join(base,'codex-chat-sessions.json'), claimsFile=path.join(base,'notification-claims.json'), feedbackFile=path.join(base,'advisor-feedback.json');
  fs.mkdirSync(base, { recursive:true }); if (!fs.existsSync(file)) fs.writeFileSync(file, '');
  knownIds = new Set(readEvents(file).map(event => event.id));
  const deliveryQueue = new DeliveryQueue(queueFile);
  const usageStore = new UsageStore(usageFile, { retentionDays:vscode.workspace.getConfiguration('agentpilot').get('usageRetentionDays', 90) });
  const taskStore = new TaskStore(taskFile);
  const chatStore = new ChatSessionStore(chatFile);
  const notificationClaims = new NotificationClaims(claimsFile);
  const advisorFeedback = new AdvisorFeedbackStore(feedbackFile);
  const output = vscode.window.createOutputChannel('AgentPilot'); context.subscriptions.push(output);
  const config = () => vscode.workspace.getConfiguration('agentpilot');
  const telegramConfig = async () => ({ enabled:config().get('enableTelegram', false), token:await context.secrets.get(TELEGRAM_TOKEN_KEY), chatId:await context.secrets.get(TELEGRAM_CHAT_KEY) });
  const telegramState = async () => { const current = await telegramConfig(); return { enabled:current.enabled, connected:Boolean(current.enabled && current.token && current.chatId), history:deliveryQueue.history() }; };
  const updateDashboard = async events => { if (panel) { usageStore.load(); const report=usageAnalytics(usageStore.records,new CostEstimator(config().get('pricingOverrides',{})),{days:analyticsDays}); panel.webview.html = render(events || readEvents(file), await telegramState(), report, panel.__agentpilotNonce, taskStore.recent(),{models:activeChatController?.state().models||[],result:advisorState}); } };
  const runWorker = async () => { let result; try { result=await deliveryQueue.process(await telegramConfig()); } catch { output.appendLine(`${new Date().toISOString()} Telegram ${JSON.stringify({category:'queue_worker'})}`); } if (result?.diagnostic) output.appendLine(`${new Date().toISOString()} Telegram ${JSON.stringify(result.diagnostic)}`); if (result && !['idle','disabled','busy'].includes(result.status)) await updateDashboard(); return result; };
  const refresh = async () => { if (refreshRunning) return; refreshRunning=true; try { const events=readEvents(file); const fresh=events.filter(event=>!knownIds.has(event.id)); for(const event of events) knownIds.add(event.id); const settings=config(); const enabled=settings.get('enableTelegram',false); for(const event of fresh){ if(shouldNotify(event,settings)&&notificationClaims.claim(event.id)){const message=`${event.agent} ${event.kind} · ${event.project}`;vscode.window.showInformationMessage(`AgentPilot: ${message}`);if(settings.get('enableWindowsNotifications',false))void nativeToast(context,message,output);} if(enabled&&(event.test||ALLOWED_KINDS.has(event.kind)))deliveryQueue.enqueue(event,{notifyExceptionalSessionEnd:settings.get('telegramNotifyExceptionalSessionEnd',true)}); } await updateDashboard(events); if(enabled)void runWorker(); } catch { output.appendLine(`${new Date().toISOString()} AgentPilot ${JSON.stringify({category:'event_dispatch'})}`); } finally { refreshRunning=false; } };

  const logTelegramDiagnostic = error => output.appendLine(`${new Date().toISOString()} Telegram ${JSON.stringify(safeTelegramDiagnostic(error))}`);
  const configureToken = async () => { const entered = await vscode.window.showInputBox({ title:'AgentPilot Telegram bot token', prompt:'Stored securely in VS Code SecretStorage', password:true, ignoreFocusOut:true, validateInput:value=>validToken(value)?undefined:'Enter a valid Telegram bot token' }); if (!entered) return; const token=normalizeToken(entered); try { await validateBotToken(token); } catch (error) { logTelegramDiagnostic(error); vscode.window.showErrorMessage(`AgentPilot: ${describeTelegramError(error)}`); return; } try { await context.secrets.store(TELEGRAM_TOKEN_KEY, token); } catch { output.appendLine(`${new Date().toISOString()} Telegram ${JSON.stringify({category:'secret_storage_write'})}`); vscode.window.showErrorMessage('AgentPilot: Token is valid, but VS Code SecretStorage could not save it. Check VS Code credential storage and retry.'); return; } vscode.window.showInformationMessage('AgentPilot: Telegram bot token validated and stored securely.'); await updateDashboard(); };
  const configureChat = async () => { const chatId = await vscode.window.showInputBox({ title:'AgentPilot Telegram chat ID', prompt:'Numeric chat ID or @channel username; stored in SecretStorage', ignoreFocusOut:true, validateInput:value=>validChatId(value)?undefined:'Enter a numeric chat ID or valid @channel username' }); if (!chatId) return; try { await context.secrets.store(TELEGRAM_CHAT_KEY, chatId); } catch { vscode.window.showErrorMessage('AgentPilot: VS Code SecretStorage could not save the chat ID. Check VS Code credential storage and retry.'); return; } vscode.window.showInformationMessage('AgentPilot: Telegram chat ID stored securely.'); await updateDashboard(); };
  const testTelegram = async () => { const current=await telegramConfig(); if(!current.enabled){vscode.window.showWarningMessage('AgentPilot: Enable Telegram before sending a test.');return;} const queued=deliveryQueue.enqueue({id:`telegram-test-${Date.now()}`,time:new Date().toISOString(),agent:'test',kind:'completed',project:path.basename(vscode.workspace.workspaceFolders?.[0]?.uri.fsPath||'demo'),test:true}); const result=queued.status==='queued'?await runWorker():queued; vscode.window.showInformationMessage(`AgentPilot: Telegram test ${result.status}.`); };
  const diagnoseTelegram = async () => { try { await validateBotToken('12345:abcdefghijklmnopqrstuvwxyz'); vscode.window.showWarningMessage('AgentPilot: Unexpected Telegram diagnostic response.'); } catch (error) { logTelegramDiagnostic(error); const diagnostic=safeTelegramDiagnostic(error); if(diagnostic.category==='invalid_token'&&diagnostic.httpStatus===401&&diagnostic.contentType==='application/json') vscode.window.showInformationMessage('AgentPilot: Telegram connectivity is healthy (Bot API returned expected JSON/HTTP 401 for a synthetic token).'); else { output.show(true); vscode.window.showWarningMessage(`AgentPilot: Telegram connectivity diagnostic found ${diagnostic.category}. See the AgentPilot output channel.`); } } };
  const testWindowsNotification = async () => { const result=await nativeToast(context,'AgentPilot native Windows notification test',output); const message=`AgentPilot: ${windowsResultMessage(result)}`; if(result.ok)vscode.window.showInformationMessage(message);else{output.show(true);vscode.window.showErrorMessage(message);} };
  const workspaceFolder=vscode.workspace.workspaceFolders?.[0],configuredCodex=config().get('codexCliPath',process.platform==='win32'?'codex.exe':'codex');
  activeChatController=new CodexChatController({store:chatStore,usageStore,executable:resolveExecutable(configuredCodex),cwd:workspaceFolder?.uri.fsPath||context.extensionPath});
  activeChatController.on('lifecycle',event=>{const result=appendEvent(file,event);output.appendLine(`${new Date().toISOString()} Codex chat ${JSON.stringify({kind:event.kind,project:event.project,stored:result.stored})}`);void refresh();});
  activeChatController.on('diagnostic',diagnostic=>output.appendLine(`${new Date().toISOString()} Codex chat ${JSON.stringify({category:diagnostic.category||'app_server'})}`));
  activeChatController.on('approval',async request=>{const prompt=approvalPrompt(request),choice=await vscode.window.showWarningMessage(prompt.message,prompt.options,...prompt.buttons);try{activeChatController.respondApproval(request.requestId,approvalDecision(choice));}catch{output.appendLine(`${new Date().toISOString()} Codex chat ${JSON.stringify({category:'approval_response'})}`);}});
  const chatProvider=new ChatViewProvider({controller:activeChatController,vscode,extensionUri:context.extensionUri,output});
  context.subscriptions.push(vscode.window.registerWebviewViewProvider('agentpilot.chat',chatProvider,{webviewOptions:{retainContextWhenHidden:true}}));
  activeTaskRunner=new CodexTaskRunner({taskStore,usageStore,timeoutMs:config().get('codexTaskTimeoutMinutes',30)*60000});
  {const configured=config().get('codexCliPath',process.platform==='win32'?'codex.exe':'codex');output.appendLine(`${new Date().toISOString()} Codex task ${JSON.stringify({category:'executable_resolution',resolved:Boolean(resolveExecutable(configured)),configuredAsPath:path.isAbsolute(configured)})}`);}
  activeTaskRunner.on('lifecycle',event=>{const result=appendEvent(file,event);output.appendLine(`${new Date().toISOString()} Codex task ${JSON.stringify({kind:event.kind,project:event.project,errorCategory:event.errorCategory||null,stored:result.stored})}`);void refresh();});
  activeTaskRunner.on('change',()=>void updateDashboard());
  const runCodexTask=async()=>{const folder=vscode.workspace.workspaceFolders?.[0];if(!folder){vscode.window.showErrorMessage('AgentPilot: Open a workspace folder before running a Codex task.');return;}if(!vscode.workspace.isTrusted){vscode.window.showErrorMessage('AgentPilot: Trust this workspace before running a Codex task.');return;}if(activeTaskRunner.active){vscode.window.showWarningMessage('AgentPilot: A Codex task is already running.');return;}const configured=config().get('codexCliPath',process.platform==='win32'?'codex.exe':'codex'),executable=resolveExecutable(configured);if(!executable){output.appendLine(`${new Date().toISOString()} Codex task ${JSON.stringify({category:'executable_not_found',configuredAsPath:path.isAbsolute(configured)})}`);vscode.window.showErrorMessage('AgentPilot: Native Codex executable not found. Set AgentPilot: Codex CLI Path to the absolute path of a supported codex.exe.');return;}const prompt=await vscode.window.showInputBox({title:'AgentPilot: Run Codex Task',prompt:'Describe the task. AgentPilot does not store this text.',ignoreFocusOut:true,validateInput:value=>value.trim()?undefined:'Enter a task.'});if(!prompt)return;const choice=await vscode.window.showWarningMessage(`Run this Codex task in ${path.basename(folder.uri.fsPath)} using your existing Codex configuration and approval policy?`,{modal:true},'Run');if(choice!=='Run')return;try{activeTaskRunner.start({executable,cwd:folder.uri.fsPath,prompt,model:config().get('codexTaskModel','')||undefined});vscode.window.showInformationMessage('AgentPilot: Codex task started.');}catch(error){const category=error.agentpilotCategory||'process_start';output.appendLine(`${new Date().toISOString()} Codex task ${JSON.stringify({category})}`);vscode.window.showErrorMessage(`AgentPilot: Could not start Codex (${category}). Check AgentPilot: Codex CLI Path.`);}};
  const cancelCodexTask=async()=>{if(!activeTaskRunner.active){vscode.window.showInformationMessage('AgentPilot: No Codex task is running.');return;}const choice=await vscode.window.showWarningMessage('Cancel the running AgentPilot-owned Codex task?',{modal:true},'Cancel Task');if(choice==='Cancel Task')activeTaskRunner.cancel();};
  const importUsage = async () => {
    const selected=await vscode.window.showOpenDialog({canSelectMany:false,filters:{JSON:['json','jsonl']},title:'Import structured usage metadata'}); if(!selected?.[0]) return;
    let text; try{text=fs.readFileSync(selected[0].fsPath,'utf8');}catch{vscode.window.showErrorMessage('AgentPilot: Could not read the selected usage file.');return;}
    let stored=0, skipped=0; const lines=text.trim().startsWith('[')?[text]:text.split(/\r?\n/).filter(Boolean);
    for(const line of lines){try{const parsed=JSON.parse(line);const values=Array.isArray(parsed)?parsed:[parsed];for(const payload of values){const contextData={project:path.basename(vscode.workspace.workspaceFolders?.[0]?.uri.fsPath||'unknown')};const record=new CodexUsageAdapter().normalize(payload,contextData)||new ClaudeUsageAdapter().normalize(payload,contextData);if(record&&usageStore.add(record).status==='stored')stored++;else skipped++;}}catch{skipped++;}}
    await updateDashboard(); vscode.window.showInformationMessage(`AgentPilot: Imported ${stored} verified usage record(s); skipped ${skipped}.`);
  };

  watcher = fs.watch(base, (type, name) => { if (name === 'events.jsonl') void refresh(); else if(name==='usage.json') void updateDashboard(); }); poller = setInterval(()=>void refresh(), 2500); workerTimer=setInterval(()=>void runWorker(),5000);
  const handleDashboardMessage=async message=>{if(!validDashboardMessage(message)){output.appendLine(`${new Date().toISOString()} AgentPilot ${JSON.stringify({category:'invalid_webview_message'})}`);return;}if(message.action==='toggle')await config().update('enableTelegram',!config().get('enableTelegram',false),vscode.ConfigurationTarget.Global);else if(message.action==='token')await configureToken();else if(message.action==='chat')await configureChat();else if(message.action==='test')await testTelegram();else if(message.action==='importUsage')await importUsage();else if(message.action==='runCodex')await runCodexTask();else if(message.action==='cancelCodex')await cancelCodexTask();else if(message.action==='advisorRecommend'){advisorFeedback.items=advisorFeedback.read();advisorState=recommendFromDashboardMessage(message,{models:activeChatController.state().models,usageRecords:usageStore.records,feedback:advisorFeedback.items});}else if(message.action==='advisorApply'){const available=activeChatController.state().models.find(model=>model.id===message.model&&!model.hidden);if(!available){output.appendLine(`${new Date().toISOString()} Advisor ${JSON.stringify({category:'model_unavailable'})}`);vscode.window.showErrorMessage('AgentPilot Advisor: That model is no longer available. Refresh and try again.');}else{await activeChatController.newSession(available.id);await vscode.commands.executeCommand('agentpilot.openChat');}}else if(message.action==='advisorFeedback'){const result=advisorFeedback.add(message);vscode.window.showInformationMessage(result.stored?'AgentPilot: Subjective feedback stored locally.':'AgentPilot: Feedback was not stored.');}else if(message.action==='range')analyticsDays=Math.min(3650,Math.max(0,Number(message.id)||0));else if(message.action==='retry'){const item=deliveryQueue.items.find(candidate=>candidate.sourceEventId===message.id),warning=item?.status==='uncertain'?'Telegram may already have delivered this notification. Check the chat before retrying.':'Retry this failed notification?';const choice=await vscode.window.showWarningMessage(warning,{modal:true},'Retry');if(choice==='Retry'&&deliveryQueue.manualRetry(message.id)===true)void runWorker();}await updateDashboard();};
  context.subscriptions.push(vscode.commands.registerCommand('agentpilot.openDashboard',async()=>{panel=vscode.window.createWebviewPanel('agentpilot','AgentPilot Dashboard',vscode.ViewColumn.One,{enableScripts:true});panel.__agentpilotNonce=require('crypto').randomBytes(16).toString('hex');panel.webview.onDidReceiveMessage(handleDashboardMessage,undefined,context.subscriptions);panel.onDidDispose(()=>panel=undefined);if(vscode.workspace.isTrusted)await activeChatController.ensureClient().catch(error=>output.appendLine(`${new Date().toISOString()} Advisor ${JSON.stringify({category:error.code||'model_discovery'})}`));await updateDashboard();}));
  context.subscriptions.push(vscode.commands.registerCommand('agentpilot.openChat',()=>vscode.commands.executeCommand('workbench.view.extension.agentpilot')));
  context.subscriptions.push(vscode.commands.registerCommand('agentpilot.testNotification', () => { appendEvent(file, { time:new Date().toISOString(), agent:'test', kind:'completed', project:path.basename(vscode.workspace.workspaceFolders?.[0]?.uri.fsPath || 'demo'), source:'test', test:true }); refresh(); vscode.window.showInformationMessage('AgentPilot test event recorded.'); }));
  context.subscriptions.push(vscode.commands.registerCommand('agentpilot.testWindowsNotification', testWindowsNotification));
  context.subscriptions.push(vscode.commands.registerCommand('agentpilot.configureTelegramToken', configureToken));
  context.subscriptions.push(vscode.commands.registerCommand('agentpilot.configureTelegramChatId', configureChat));
  context.subscriptions.push(vscode.commands.registerCommand('agentpilot.testTelegram', testTelegram));
  context.subscriptions.push(vscode.commands.registerCommand('agentpilot.diagnoseTelegramConnectivity', diagnoseTelegram));
  context.subscriptions.push(vscode.commands.registerCommand('agentpilot.importUsage', importUsage));
  context.subscriptions.push(vscode.commands.registerCommand('agentpilot.runCodexTask',runCodexTask));
  context.subscriptions.push(vscode.commands.registerCommand('agentpilot.cancelCodexTask',cancelCodexTask));
  context.subscriptions.push({ dispose() { activeChatController?.dispose(); activeTaskRunner?.dispose(); watcher?.close(); clearInterval(poller); clearInterval(workerTimer); } });
}

function deactivate() { activeChatController?.dispose(); activeTaskRunner?.dispose(); watcher?.close(); clearInterval(poller); clearInterval(workerTimer); }
module.exports = { activate, advisorMarkup, deactivate, escapeHtml, nativeToast, recommendFromDashboardMessage, render, shouldNotify, taskMarkup, usageMarkup, validDashboardMessage, windowsResultMessage };
